"""Extract text from a PDF with PyMuPDF.

Thin stdin/stdout JSON adapter so the Node resume parser can read PDFs with the
same engine that produces them (PyMuPDF), which keeps extraction reliable for
both user-uploaded PDFs and PDFs generated by this app. pdfjs-based parsers
mangle some CJK glyphs in PyMuPDF-generated files.
"""

import json
import sys

import pymupdf


def main():
    payload = json.load(sys.stdin)
    path = payload.get("filePath")
    if not path:
        print(json.dumps({"ok": False, "error": "missing filePath"}, ensure_ascii=False))
        return
    try:
        document = pymupdf.open(path)
        try:
            pages = [page.get_text() for page in document]
        finally:
            document.close()
        print(json.dumps({"ok": True, "text": "\n".join(pages)}, ensure_ascii=False))
    except Exception as error:  # noqa: BLE001 - report anything to the caller
        print(json.dumps({"ok": False, "error": str(error)}, ensure_ascii=False))


if __name__ == "__main__":
    main()
